#include "board.h"
#include "pin_mux.h"
#include "peripherals.h"
#include "logger.h"

int main(void) {
    // Initialize board hardware, pins, and clocks generated by NXP SDK
    BOARD_InitBootPins();
    BOARD_InitBootClocks();
    BOARD_InitBootPeripherals();

    // Initialize FreeRTOS synchronization primitives (Mutex & Queue)
    logger_init_primitives();

    // Create FreeRTOS tasks
    xTaskCreate(vSensorLoggerTask, "SensorLog", configMINIMAL_STACK_SIZE + 128, NULL, tskIDLE_PRIORITY + 1, NULL);
    xTaskCreate(vCliTask, "CLI_Task", configMINIMAL_STACK_SIZE + 128, NULL, tskIDLE_PRIORITY + 1, NULL);

    // Start the FreeRTOS scheduler
    vTaskStartScheduler();

    // Code should never reach here unless out of heap memory
    for (;;) {
        __WFI();
    }
}